import torch
import safetensors.torch

def main():
    import openpi.models.pi0_config as pi0_config
    import openpi.models_pytorch.pi0_pytorch as pi0_pytorch

    print("=" * 60)
    print("PART 1: Build model and load weights")
    print("=" * 60)

    model_config = pi0_config.Pi0Config(
        paligemma_variant="gemma_2b_lora",
        action_expert_variant="gemma_300m_lora",
    )
    model = pi0_pytorch.PI0Pytorch(model_config).to("cuda:0")
    total_params = sum(p.numel() for p in model.parameters())
    trainable_params = sum(p.numel() for p in model.parameters() if p.requires_grad)
    print(f"Total params: {total_params:,}")
    print(f"Trainable params: {trainable_params:,}")

    # Load weights
    weight_path = "/root/autodl-tmp/openpi_weights/pi0_base"
    model_path = os.path.join(weight_path, "model.safetensors")

    test_p = dict(model.named_parameters())['action_in_proj.weight']
    print(f"BEFORE load - mean={test_p.data.float().mean():.6f}, std={test_p.data.float().std():.6f}")

    missing, unexpected = safetensors.torch.load_model(model, model_path)
    print(f"Missing: {len(missing)}, Unexpected: {len(unexpected)}")

    test_p = dict(model.named_parameters())['action_in_proj.weight']
    print(f"AFTER load - mean={test_p.data.float().mean():.6f}, std={test_p.data.float().std():.6f}")

    print("\n" + "=" * 60)
    print("PART 2: Data loader with norm_stats")
    print("=" * 60)

    import openpi.training.config as _config
    from openpi.training.optimizer import CosineDecaySchedule
    import openpi.training.data_loader as _data

    config = _config.TrainConfig(
        name="baseline_spatial_bowl",
        project_name="colliforce-vla",
        exp_name="verify_test",
        model=model_config,
        data=_config.LeRobotLiberoDataConfig(
            repo_id="safelibero_spatial",
            base_config=_config.DataConfig(prompt_from_task=True),
            extra_delta_transform=True,
        ),
        pytorch_weight_path=weight_path,
        freeze_filter=model_config.get_freeze_filter(),
        ema_decay=None,
        lr_schedule=CosineDecaySchedule(
            warmup_steps=1000, peak_lr=2.5e-5,
            decay_steps=30000, decay_lr=2.5e-6,
        ),
        num_train_steps=2,
        batch_size=2,
        save_interval=2,
        log_interval=1,
        checkpoint_base_dir="/root/autodl-tmp/checkpoints",
        seed=0,
        wandb_enabled=False,
        overwrite=True,
    )

    # Use num_workers=0 to avoid multiprocessing issues
    import torch.utils.data
    loader = _data.create_data_loader(config, framework="pytorch", shuffle=True)

    # Monkey-patch to use num_workers=0
    data_config = loader.data_config()
    if hasattr(data_config, 'norm_stats') and data_config.norm_stats:
        print(f"norm_stats keys: {list(data_config.norm_stats.keys())}")
    else:
        print("WARNING: norm_stats is None or empty!")

    # Get one batch manually
    dataset = loader.dataset if hasattr(loader, 'dataset') else None
    print(f"Loader type: {type(loader)}")
    print(f"Dataset type: {type(dataset) if dataset else 'N/A'}")

    # Try to get data
    import jax

    print("\n" + "=" * 60)
    print("PART 3: Forward pass loss check")
    print("=" * 60)

    model.train()

    for i, batch in enumerate(loader):
        if i > 0:
            break
        observation, actions = batch
        observation = jax.tree.map(lambda x: x.to("cuda:0"), observation)
        actions = actions.to(torch.float32).to("cuda:0")
        print(f"actions shape: {actions.shape}, range: [{actions.min():.3f}, {actions.max():.3f}]")
        print(f"state shape: {observation.state.shape}")

        with torch.no_grad():
            losses = model(observation, actions)
            loss = losses.mean()
            print(f"\nLoss with loaded weights: {loss.item():.4f}")
            print(f"Expected ~0.2 (good) or ~100+ (weights not loaded)")

    # Random init comparison
    print("\n" + "=" * 60)
    print("PART 4: Random init comparison")
    print("=" * 60)

    model2 = pi0_pytorch.PI0Pytorch(model_config).to("cuda:0")
    model2.train()
    with torch.no_grad():
        losses2 = model2(observation, actions)
        loss2 = losses2.mean()
        print(f"Random init loss: {loss2.item():.4f}")

    del model2
    torch.cuda.empty_cache()

    print("\n" + "=" * 60)
    print("PART 5: suffix_out shape for SDF integration")
    print("=" * 60)

    # Hook to capture suffix_out
    suffix_out_captured = {}
    def hook_fn(module, input, output):
        # action_out_proj receives suffix_out as input
        suffix_out_captured['value'] = input[0].detach()

    handle = model.action_out_proj.register_forward_hook(hook_fn)
    with torch.no_grad():
        _ = model(observation, actions)
    handle.remove()

    if 'value' in suffix_out_captured:
        so = suffix_out_captured['value']
        print(f"suffix_out shape: {so.shape}")
        print(f"suffix_out dtype: {so.dtype}")
        print(f"suffix_out mean: {so.mean():.4f}, std: {so.std():.4f}")
        print(f"Mean-pooled features shape: {so.mean(dim=1).shape}")

    del model
    torch.cuda.empty_cache()

    print("\n" + "=" * 60)
    print("VERIFICATION COMPLETE")
    print("=" * 60)

if __name__ == '__main__':
    main()
